Consider the following C program:
<pre><code>
#include < stdio.h >

void stringcopy(char *, char *);

int main(){
    char a[30] = "@#Hello World!";
    stringcopy(a, a + 2);
    printf("%s\n", a);
    return 0;
}

void stringcopy(char *s, char *t) {
    while(*t)
        *s++ = *t++;
}
</pre></code>

Which ONE of the following will be the output of the program?

Consider the following C program:
<pre><code>
#include < stdio.h >

int main(){
    int a;
    int arr[5] = {30,50,10};
    int *ptr;
    ptr = &arr[0] + 1;
    a = *ptr;
    (*ptr)++;
    ptr++;
    printf("%d", a + (*ptr) + arr[1]);
    return 0;
}
</pre></code>
The output of the above program is ___________. (Answer in integer)

Consider the following C program:
<pre><code>
#include < stdio.h >

int g(int n) {
    return (n+10);
}

int f(int n) {
    return g(n*2);
}

int main() {
    int sum, n;
    sum=0;
    for (n=1; n<3; n++)
        sum += g(f(n));
    printf ("%d", sum);
    return 0;
}
</pre></code>
The output of the given C program is ________. (Answer in integer)
